Refactor this legacy Angular service to @ngrx/signals, following our project's architecture baseline. Existing components use products$ and inStockProducts$ via the async pipe — show me how to migrate the template too. Here is the service:

```typescript
@Injectable({ providedIn: 'root' })
export class ProductsService {
  private readonly _products$ = new BehaviorSubject<ProductDto[]>([]);
  private readonly _isLoading$ = new BehaviorSubject<boolean>(false);
  readonly products$ = this._products$.asObservable();
  readonly isLoading$ = this._isLoading$.asObservable();
  readonly inStockProducts$ = this.products$.pipe(map(p => p.filter(x => x.stock > 0)));

  constructor(private http: HttpClient) {}

  loadAll() {
    this._isLoading$.next(true);
    this.http.get<ProductDto[]>('/api/products').subscribe({
      next: products => { this._products$.next(products); this._isLoading$.next(false); },
      error: () => this._isLoading$.next(false),
    });
  }
}
```

The products list is only shown on the catalog page (src/features/catalog/).
